+++ b/test/transform/resource/before/BuilderDefaultsGenericsInferred.java
@@ -0,0 +1,1 @@
+import lombok.Builder;
+import lombok.Value;
+import lombok.experimental.SuperBuilder;
+
+@Builder
+public class BuilderDefaultsGenericsInferred {
+	@Builder.Default
+	String foo = doSth(MyClass.myInt(), MyClass.myChar());
+
+	@SuperBuilder
+	public static class SuperBuilderWithGenerics {
+		@Builder.Default
+		String foo = doSth(MyClass.myInt(), MyClass.myChar());
+	}
+
+	@Value
+	static class MyClass<T> {
+		T value;
+
+		static MyClass<Integer> myInt() {
+			return new MyClass<Integer>(42);
+		}
+
+		static MyClass<Character> myChar() {
+			return new MyClass<Character>('A');
+		}
+	}
+
+	static String doSth(MyClass<Integer> i, MyClass<Character> c) {
+		return i.value.toString() + c.value.toString();
+	}
+
+	public static void main(String[] args) {
+		if (!"42A".equals(BuilderDefaultsGenericsInferred.builder().build().foo)) throw new AssertionError();
+		if (!"custom".equals(BuilderDefaultsGenericsInferred.builder().foo("custom").build().foo)) throw new AssertionError();
+		if (!"42A".equals(SuperBuilderWithGenerics.builder().build().foo)) throw new AssertionError();
+		if (!"custom".equals(SuperBuilderWithGenerics.builder().foo("custom").build().foo)) throw new AssertionError();
+	}
+}
