+import java.io.File;
+import lombok.AbstractRunTests;
+import lombok.DirectoryRunner;
+import lombok.RunTestsViaDelombok;
+import lombok.RunTestsViaEcj;
+import lombok.transform.TestLombokFilesIdempotent;
+import lombok.transform.TestWithDelombok;
+import lombok.transform.TestWithEcj;
+
+public class RunFixtures {
+	public static void main(String[] args) throws Throwable {
+		boolean ecj = args[0].equals("ecj");
+		DirectoryRunner.TestParams params = ecj ? new TestWithEcj() : args[0].equals("idempotent") ? new TestLombokFilesIdempotent() : new TestWithDelombok();
+		for (int i = 1; i < args.length; i++) {
+			AbstractRunTests runner = ecj ? new RunTestsViaEcj() : new RunTestsViaDelombok();
+			DirectoryRunner.FileTester tester = runner.createTester(params, new File(params.getBeforeDirectory(), args[i]), ecj ? "eclipse" : "javac", params.getVersion());
+			if (tester == null) throw new AssertionError("Fixture skipped: " + args[i]);
+			tester.runTest();
+			System.out.println("PASS " + args[0] + " " + args[i]);
+		}
+	}
+}
